import{_ as l,o as t,c as o,a2 as d}from"./chunks/framework.BUwdTBzS.js";const k=JSON.parse('{"title":"按需-Skill设计-跨文件协作","description":"Skill 设计哲学详细规范与跨文件协作模式（按需规则，由 AI行为规范.mdc 引用触发）","frontmatter":{"title":"按需-Skill设计-跨文件协作","description":"Skill 设计哲学详细规范与跨文件协作模式（按需规则，由 AI行为规范.mdc 引用触发）"},"headers":[],"relativePath":"rules/按需-Skill设计-跨文件协作.md","filePath":"rules/按需-Skill设计-跨文件协作.md","lastUpdated":null}'),a={name:"rules/按需-Skill设计-跨文件协作.md"};function i(r,e,c,s,n,h){return t(),o("div",null,[...e[0]||(e[0]=[d('<blockquote><p>📄 本页由源文件 <code>rules/按需-Skill设计-跨文件协作.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="按需-skill设计-跨文件协作" tabindex="-1">按需-Skill设计-跨文件协作 <a class="header-anchor" href="#按需-skill设计-跨文件协作" aria-label="Permalink to &quot;按需-Skill设计-跨文件协作&quot;">​</a></h1><blockquote><p>本文件由 <code>rules/AI行为规范.mdc</code> § Skill 设计哲学 / § 跨文件协作设计模式 引用触发；alwaysApply=false 节省常驻 Token。 触发场景：创建/重构 Skill、Skill 多文件改动、Skill 实施沉淀、跨 Skill 协作。</p></blockquote><hr><h2 id="一、skill-设计哲学-强制-2026-05-15-沉淀" tabindex="-1">一、Skill 设计哲学（强制，2026-05-15 沉淀） <a class="header-anchor" href="#一、skill-设计哲学-强制-2026-05-15-沉淀" aria-label="Permalink to &quot;一、Skill 设计哲学（强制，2026-05-15 沉淀）&quot;">​</a></h2><blockquote><p><strong>核心原则</strong>：<strong>确定性用代码，模糊性用 LLM</strong>。 来源：dev-flow v3 重构（2026-05-14）实战验证 + Anthropic Claude Code Hooks / 12-factor agents 共识。 框架原则与数据驱动落地手法的完整论述见 <code>skills/dev-flow/references/core-principles.md</code> §19 / §20。</p></blockquote><h3 id="_1-1-skill-创建-重构「决策清单」必答项" tabindex="-1">1.1 Skill 创建/重构「决策清单」必答项 <a class="header-anchor" href="#_1-1-skill-创建-重构「决策清单」必答项" aria-label="Permalink to &quot;1.1 Skill 创建/重构「决策清单」必答项&quot;">​</a></h3><blockquote><p>接在「先调研 → 决策清单 → 用户确认 → 实现」流程的「决策清单」环节。 列出本 Skill 涉及的所有规则/检查项，逐条标注「确定性（→ 脚本/lint/配置）」or「模糊性（→ 提示词/LLM）」：</p></blockquote><table tabindex="0"><thead><tr><th>规则/能力</th><th>类型</th><th>实现方式</th><th>兜底机制</th></tr></thead><tbody><tr><td>例：检查文件存在</td><td>确定性</td><td>bash <code>[ -f ]</code></td><td>exit code</td></tr><tr><td>例：检查 JSON 格式</td><td>确定性</td><td><code>jq</code> / <code>ajv</code></td><td>exit code</td></tr><tr><td>例：检查行数 / 命名规范</td><td>确定性</td><td>lint 脚本</td><td>exit code</td></tr><tr><td>例：判断方案是否优雅</td><td>模糊性</td><td>LLM</td><td>用户决策</td></tr><tr><td>例：判断根因是否合理</td><td>模糊性</td><td>LLM</td><td>用户决策</td></tr></tbody></table><blockquote><p><strong>任何标注为「确定性」的规则，必须有对应脚本/配置/Schema 兜底，不允许只写在 SKILL.md 提示词里</strong>。</p></blockquote><h3 id="_1-2-反模式-违反即拒收" tabindex="-1">1.2 反模式（违反即拒收） <a class="header-anchor" href="#_1-2-反模式-违反即拒收" aria-label="Permalink to &quot;1.2 反模式（违反即拒收）&quot;">​</a></h3><ul><li>❌ 把&quot;某检查不可跳过&quot;写成 SKILL.md 提示词依赖 AI 记忆，没有 <code>.validated</code> 物理事实兜底</li><li>❌ 同一条规则在 N 个文档里重复维护（应该有「单一权威源」：脚本是真相，文档只引用不重复）</li><li>❌ 设计阶段没做拆分，先把所有规则全塞提示词，事后再重构（dev-flow v3 走的就是这条弯路，重构成本极高，应避免重蹈覆辙）</li></ul><h3 id="_1-3-正确范式-dev-flow-v3-已落地-可参考" tabindex="-1">1.3 正确范式（dev-flow v3 已落地，可参考） <a class="header-anchor" href="#_1-3-正确范式-dev-flow-v3-已落地-可参考" aria-label="Permalink to &quot;1.3 正确范式（dev-flow v3 已落地，可参考）&quot;">​</a></h3><ul><li>程序化优先：能进 <code>config/gates.yaml</code> / <code>scripts/lints/</code> 的就不进提示词</li><li>单一权威源：脚本/配置是规则真相</li><li>物理事实兜底：<code>.validated</code> 由脚本原子创建，AI 不可绕过</li><li>元门控守护：用 <code>refactor-gate.sh</code> 类脚本守护规则系统本身</li><li>数据驱动 + fallback：枚举/列表/映射类数据放 YAML（主路径）+ 保留硬编码 fallback（兜底）；详见 <code>skills/dev-flow/references/core-principles.md</code> §20.2 双层结构 + §20.3 配置驱动测试模式</li></ul><hr><h2 id="二、跨文件协作设计模式-同形-×2-promote-2026-05-15" tabindex="-1">二、跨文件协作设计模式（同形 ×2 promote，2026-05-15） <a class="header-anchor" href="#二、跨文件协作设计模式-同形-×2-promote-2026-05-15" aria-label="Permalink to &quot;二、跨文件协作设计模式（同形 ×2 promote，2026-05-15）&quot;">​</a></h2><blockquote><p><strong>背景</strong>：Skill 多文件改动 / 跨 Skill 协作 / Skill 实施沉淀时，规则文档↔步骤文档↔脚本实现三方必须形成「单一权威源 + 双向引用」的协作网（源于同形 ×2 病灶提升 + 三层防线 P0/P1/P2 实战沉淀）。</p></blockquote><h3 id="_2-1-强制套用清单-修改-≥2-个文件且涉及规则-步骤-脚本协作时" tabindex="-1">2.1 强制套用清单（修改 ≥2 个文件且涉及规则/步骤/脚本协作时） <a class="header-anchor" href="#_2-1-强制套用清单-修改-≥2-个文件且涉及规则-步骤-脚本协作时" aria-label="Permalink to &quot;2.1 强制套用清单（修改 ≥2 个文件且涉及规则/步骤/脚本协作时）&quot;">​</a></h3><ol><li><strong>写入前问清楚</strong>：「这条规则的『真相』在哪个文件？」（脚本/YAML/Schema 永远优先于 markdown 提示词）</li><li><strong>A → B 引用，必须配 B → A 反向引用</strong>：自检命令是 <code>grep -nE &quot;B-keyword&quot; A.md &amp;&amp; grep -nE &quot;A-keyword&quot; B.md</code>，任一为空 → 断链待修</li><li><strong>落地后必须 grep 实测</strong>：禁止凭&quot;我刚才说要做&quot;的记忆当作&quot;已经做了&quot;，所有承诺必须用 <code>grep</code>/<code>ls</code> 工具实测验证后才能宣告完成（与 § 验证行为规范 「承诺一致性必须 grep 实测」一致）</li><li><strong>脚本顶部注释也要双向引用</strong>：脚本是规则真相时，顶部注释里要明文写「← references/xxx.md §Y / steps/zzz.md §Z」，避免脚本被孤立修改</li><li><strong>跨文档变更留迁移指向</strong>：源文件改动如果同时影响多个文档，必须在每个变更点留下「详见 X 文件 §Y」的反向跳板</li></ol><h3 id="_2-2-反模式-违反即拒收" tabindex="-1">2.2 反模式（违反即拒收） <a class="header-anchor" href="#_2-2-反模式-违反即拒收" aria-label="Permalink to &quot;2.2 反模式（违反即拒收）&quot;">​</a></h3><ul><li>❌ 在 ▶️ 选项里承诺「§A 与 §B 已建立呼应」，实际只读了 §A 的引用，没动手扩展 §B 的反向引用 → 单向断链</li><li>❌ 在 N 个文档里重复维护同一条规则的内容（应该有「单一权威源」：脚本是真相，文档只引用不重复）</li><li>❌ 按&quot;自己刚写过 plan.md/devlog.md，肯定有&quot;的记忆免去物理事实校验</li></ul><h3 id="_2-3-参考实施案例-×2-已-promote" tabindex="-1">2.3 参考实施案例（×2 已 promote） <a class="header-anchor" href="#_2-3-参考实施案例-×2-已-promote" aria-label="Permalink to &quot;2.3 参考实施案例（×2 已 promote）&quot;">​</a></h3><ul><li>案例 ×1：<code>knowledge-loop</code> ↔ <code>dev-flow</code> 的 sync 滞后检测协作</li><li>案例 ×2：<code>step-7-commit.md §K</code> ↔ <code>gate-validator.md §「dev-logs 物理事实兜底（P0/P1 闭环）」</code> ↔ <code>validate-output.sh / devlog-integrity-lint.sh</code> 三方双向引用闭环</li></ul><hr><h2 id="三、引用回链-双向闭环" tabindex="-1">三、引用回链（双向闭环） <a class="header-anchor" href="#三、引用回链-双向闭环" aria-label="Permalink to &quot;三、引用回链（双向闭环）&quot;">​</a></h2><ul><li>主文件：<code>rules/AI行为规范.mdc</code> § Skill 设计哲学 / § 跨文件协作设计模式（保留 ≤5 行核心断言 + 引用本文件）</li><li>框架原则：<code>skills/dev-flow/references/core-principles.md</code> §19 / §20</li></ul>',26)])])}const p=l(a,[["render",i]]);export{k as __pageData,p as default};
